update public.products set beneficiary_details = coalesce(beneficiary_details,'{}'::jsonb) || '{"goals":["technology","governance","innovation"],"organizationSizes":["medium","large","enterprise"],"maturityLevels":["developing","established"],"audience":{"ar":"مكاتب البنية المؤسسية وفرق الهندسة ولجان التقنية التي تحتاج قرارًا موحدًا حول التقنيات التي تتبناها أو تجربها أو توقفها.","en":"EA offices, engineering teams and technology boards that need one shared decision on which technologies to adopt, trial, assess or hold."},"notFor":{"ar":"الجهات الصغيرة ذات تقنيات قليلة ثابتة، أو من يبحث عن أداة لإدارة المشاريع أو الأصول.","en":"Small organisations with a few stable technologies, or teams looking for project or asset management."},"prerequisites":{"ar":["قائمة أولية بالتقنيات المستخدمة","لجنة أو مالك يعتمد التصنيفات","معايير تقييم متفق عليها"],"en":["An initial list of technologies in use","A board or owner who approves ratings","Agreed assessment criteria"]},"integrations":{"ar":["تصدير واستيراد Excel/CSV","ربط بمشهد التطبيقات (APM)","مشاركة الرادار عبر رابط"],"en":["Excel/CSV import and export","Link to the application landscape (APM)","Share the radar via link"]},"limitations":{"ar":["قيمة الرادار تعتمد على تحديثه دوريًا","لا يقيس الأداء الفني للتقنيات آليًا"],"en":["Its value depends on regular reviews","Does not measure technical performance automatically"]},"exampleOutput":{"ar":"رادار مرئي بأربع حلقات (تبنَّ، جرّب، قيّم، أوقف) لكل مجال، مع مبرر كل قرار وتاريخ مراجعته.","en":"A visual four-ring radar (Adopt, Trial, Assess, Hold) per quadrant, with the rationale and review date for every decision."}}'::jsonb where id='radar';
update public.products set beneficiary_details = coalesce(beneficiary_details,'{}'::jsonb) || '{"goals":["architecture","applications","technology","governance"],"organizationSizes":["medium","large","enterprise"],"maturityLevels":["developing","established"],"audience":{"ar":"الجهات التي تريد إدارة البنية المؤسسية كاملة في مكان واحد: القدرات والتطبيقات والتقنيات والتكاليف والحوكمة.","en":"Organisations that want to run their whole enterprise architecture in one place: capabilities, applications, technology, cost and governance."},"notFor":{"ar":"من يحتاج أداة واحدة محددة فقط، أو جهة بلا فريق مسؤول عن البنية المؤسسية.","en":"Teams needing only one specific tool, or organisations without anyone owning enterprise architecture."},"prerequisites":{"ar":["راعٍ تنفيذي وفريق بنية مؤسسية","بيانات أولية عن التطبيقات والقدرات","خطة تبنٍّ على مراحل"],"en":["An executive sponsor and an EA team","Initial application and capability data","A phased adoption plan"]},"integrations":{"ar":["استيراد Excel/CSV","تسجيل دخول موحد (SSO) حسب الإعداد","واجهات برمجية للربط مع CMDB والأنظمة المالية"],"en":["Excel/CSV import","Single sign-on (SSO) as configured","APIs to connect CMDB and finance systems"]},"limitations":{"ar":["يتطلب وقتًا لتجهيز البيانات قبل ظهور القيمة الكاملة","يحتاج حوكمة لتحديث البيانات باستمرار"],"en":["Needs time to prepare data before full value appears","Requires governance to keep data current"]},"exampleOutput":{"ar":"لوحة موحدة تربط القدرات بالتطبيقات والتقنيات وتكاليفها، مع تقارير جاهزة للإدارة العليا.","en":"One dashboard linking capabilities to applications, technologies and their costs, with executive-ready reports."}}'::jsonb where id='platform';
update public.products set beneficiary_details = coalesce(beneficiary_details,'{}'::jsonb) || '{"goals":["innovation","governance"],"organizationSizes":["medium","large","enterprise"],"maturityLevels":["starting","developing","established"],"audience":{"ar":"مكاتب الابتكار والتحول الرقمي التي تجمع أفكار الموظفين وتقيّمها وتحوّل الأفضل منها إلى مبادرات.","en":"Innovation and digital transformation offices that collect staff ideas, assess them and turn the best into initiatives."},"notFor":{"ar":"من يحتاج نظامًا لإدارة المشاريع التفصيلية أو الميزانيات بعد بدء التنفيذ.","en":"Teams needing detailed project or budget management once delivery starts."},"prerequisites":{"ar":["معايير تقييم واضحة للأفكار","لجنة أو مقيّمين معتمدين","تحديد مسار تحويل الفكرة إلى مبادرة"],"en":["Clear idea assessment criteria","A panel or approved reviewers","A defined path from idea to initiative"]},"integrations":{"ar":["تصدير Excel/CSV","ربط المبادرات بالقدرات في البنية المؤسسية","إشعارات البريد حسب الإعداد"],"en":["Excel/CSV export","Link initiatives to EA capabilities","Email notifications as configured"]},"limitations":{"ar":["لا يدير تنفيذ المشاريع بعد اعتمادها","جودة النتائج تعتمد على مشاركة الموظفين"],"en":["Does not manage project delivery after approval","Results depend on staff participation"]},"exampleOutput":{"ar":"قمع ابتكار يعرض الأفكار حسب المرحلة ودرجة التقييم، وقائمة بالمبادرات المعتمدة ومالكيها.","en":"An innovation funnel showing ideas by stage and score, plus a list of approved initiatives and their owners."}}'::jsonb where id='innovation';
update public.products set beneficiary_details = coalesce(beneficiary_details,'{}'::jsonb) || '{"goals":["applications","architecture","cost"],"organizationSizes":["medium","large","enterprise"],"maturityLevels":["starting","developing","established"],"audience":{"ar":"مكاتب البنية المؤسسية وإدارات تقنية المعلومات التي تحتاج حصرًا كاملًا للتطبيقات وعلاقاتها لاتخاذ قرارات الترشيد.","en":"EA offices and IT departments that need a full inventory of applications and their relationships to make rationalisation decisions."},"notFor":{"ar":"من يحتاج مراقبة تشغيلية لحظية للخوادم والشبكات (أدوات المراقبة أنسب).","en":"Teams needing real-time operational monitoring of servers and networks (monitoring tools fit better)."},"prerequisites":{"ar":["قائمة التطبيقات الحالية ومالكيها","تعريف القدرات أو الخدمات المدعومة","مسؤول عن تحديث البيانات"],"en":["Current application list and owners","Defined capabilities or supported services","An owner for keeping data current"]},"integrations":{"ar":["استيراد Excel/CSV","ربط برادار التقنية وإدارة التكاليف (ITFM)","واجهات برمجية مع CMDB"],"en":["Excel/CSV import","Link to the Tech Radar and cost management (ITFM)","APIs with CMDB"]},"limitations":{"ar":["لا يكتشف التطبيقات آليًا من الشبكة","دقة الخريطة تعتمد على تحديث المالكين"],"en":["Does not auto-discover applications from the network","Map accuracy depends on owners updating it"]},"exampleOutput":{"ar":"خريطة مشهد التطبيقات مع العلاقات والتكاملات، وتقييم TIME (احتفظ، استثمر، انقل، أزِل) لكل تطبيق.","en":"An application landscape map with relationships and integrations, and a TIME rating (Tolerate, Invest, Migrate, Eliminate) per application."}}'::jsonb where id='landscape';
update public.products set beneficiary_details = coalesce(beneficiary_details,'{}'::jsonb) || '{"goals":["cost","governance","technology"],"organizationSizes":["medium","large","enterprise"],"maturityLevels":["developing","established"],"audience":{"ar":"إدارات تقنية المعلومات والمالية التي تريد معرفة تكلفة كل خدمة وتطبيق وربط الإنفاق بالقرارات.","en":"IT and finance teams that want to know the cost of each service and application and link spending to decisions."},"notFor":{"ar":"من يحتاج نظامًا محاسبيًا أو لإصدار الفواتير والمدفوعات.","en":"Teams needing an accounting, invoicing or payments system."},"prerequisites":{"ar":["بيانات الإنفاق والعقود والتراخيص","قائمة الخدمات أو التطبيقات","نموذج توزيع تكاليف متفق عليه مع المالية"],"en":["Spend, contract and licence data","A list of services or applications","A cost allocation model agreed with finance"]},"integrations":{"ar":["استيراد Excel/CSV","ربط بمشهد التطبيقات (APM)","تصدير تقارير للأنظمة المالية"],"en":["Excel/CSV import","Link to the application landscape (APM)","Report export to finance systems"]},"limitations":{"ar":["لا يستبدل النظام المحاسبي (ERP)","دقة التكاليف تعتمد على جودة البيانات المدخلة"],"en":["Does not replace the accounting system (ERP)","Cost accuracy depends on input data quality"]},"exampleOutput":{"ar":"تقرير تكلفة لكل خدمة وتطبيق، مع اتجاه الإنفاق وفرص الترشيد والتراخيص غير المستخدمة.","en":"A cost report per service and application, with spending trends, savings opportunities and unused licences."}}'::jsonb where id='itfm';
update public.products set beneficiary_details = coalesce(beneficiary_details,'{}'::jsonb) || '{"goals":["architecture","governance","applications"],"organizationSizes":["medium","large","enterprise"],"maturityLevels":["starting","developing","established"],"audience":{"ar":"معماريو المؤسسة ومكاتب البنية المؤسسية الذين ينمذجون القدرات والعمليات والتطبيقات ويوثّقونها وفق أطر مثل TOGAF.","en":"Enterprise architects and EA offices who model and document capabilities, processes and applications using frameworks such as TOGAF."},"notFor":{"ar":"من يحتاج أداة رسم عامة فقط، أو أتمتة تشغيل العمليات (BPM).","en":"Teams needing only a general drawing tool, or process execution automation (BPM)."},"prerequisites":{"ar":["إطار أو منهجية بنية مؤسسية معتمدة","خريطة قدرات أولية","فريق مسؤول عن النماذج"],"en":["An adopted EA framework or method","An initial capability map","A team owning the models"]},"integrations":{"ar":["استيراد وتصدير Excel/CSV","ربط بمشهد التطبيقات ورادار التقنية","تصدير المخططات والتقارير"],"en":["Excel/CSV import and export","Link to the application landscape and Tech Radar","Export diagrams and reports"]},"limitations":{"ar":["قيد الإطلاق؛ بعض الميزات تُتاح تدريجيًا","يحتاج معرفة أساسية بالبنية المؤسسية"],"en":["Launching; some features roll out gradually","Needs basic enterprise-architecture knowledge"]},"exampleOutput":{"ar":"خريطة قدرات مؤسسية متعددة المستويات مربوطة بالعمليات والتطبيقات، مع تقييم نضج لكل قدرة.","en":"A multi-level business capability map linked to processes and applications, with a maturity rating per capability."}}'::jsonb where id='archone';